76 | /// Salt as defined in the Parquet spec

219 | fn min_log2_bytes(ndv: u64, fpp: f64) -> u8 {
220 |     let mut low = 0;
221 |     let mut high = 64;
222 |     while high > low + 1 {
223 |         let mid = (high + low) / 2;
224 |         let candidate = false_positive_probability(ndv, mid);
225 |         if candidate <= fpp {
226 |             high = mid;
227 |         } else {
228 |             low = mid;
229 |         }
230 |     }
231 |     high
232 | }
